// Ch3Props: greybox stand-ins for chapter 3 (the blacked-out office tower, server room and
// rooftop launch pad). Nothing is registered yet.
// Same contract as CommonProps.js: each builder gets { prop, size, factory } and returns an
// Object3D around the origin — metres, +Y up, front toward -Z, origin at bottom centre.
// Colours come from the palette (factory.material('key') reads greybox.<key>, which chapter 3
// can define in art/style/chapters/ch3.json). A name may only be registered by one file.
//
// Owned by the chapter 3 team member. Other chapters do not edit this file.
(function (Game) {
  'use strict';

  class Ch3Props {
    /** @param {Game.PropFactory} factory */
    static registerAll(factory) { // eslint-disable-line no-unused-vars
      // Example:
      //   factory.register('fuel_barrel', Ch3Props.fuelBarrel);
      // and below:
      //   static fuelBarrel(ctx) {
      //     const barrel = ctx.factory.cylinder(ctx.size, 'fuelBarrel');
      //     ...
      //     return barrel;
      //   }
    }
  }

  Game.Ch3Props = Ch3Props;
  Game.PropFactory.registerSet('ch3', Ch3Props.registerAll);
})((window.Game = window.Game || {}));
